<script setup lang="ts">
import { computed, onUnmounted } from 'vue'
import AppIcon from '@/components/AppIcon.vue'
import CoverArt from '@/components/CoverArt.vue'
import { buildQrDataUrl } from '@/lib/qr'
import { useAccountStore } from '@/stores/account'
import { useOfficialStore } from '@/stores/official'
import { useHistoryStore } from '@/stores/history'
const account = useAccountStore(), official = useOfficialStore(), history = useHistoryStore()
const qr = computed(() => buildQrDataUrl(account.qrUrl))
const hint = computed(() => ({ idle: account.errorMessage || '打开手机小宇宙，连接你的声音世界', checking: '正在恢复登录状态…', creating: '正在获取二维码…', waiting: '使用小宇宙 App 扫码，并在手机上确认登录', scanned: '已扫码，请在手机上确认登录', expired: '二维码已过期，点击下方按钮重新生成', error: account.errorMessage, authorized: '已连接小宇宙' })[account.phase])
onUnmounted(() => { if (!account.isLoggedIn) account.cancel() })
</script>
<template><section class="page"><header class="page-heading"><div><span class="eyebrow">YOUR PERSONAL UNIVERSE</span><h1>{{ account.isLoggedIn ? '很高兴，又听见你' : '连接你的小宇宙' }}<span class="accent">.</span></h1><p>熟悉的订阅，喜欢的声音，都在这里。</p></div></header><section v-if="!account.isLoggedIn" class="login-layout"><div class="login-story"><span class="feature-icon peach"><AppIcon name="headphones" :size="30" /></span><h2>从手机到桌面，<br />让陪伴继续。</h2><p>用小宇宙 App 扫码登录，在桌面浏览你的订阅，<br />寻找新节目，安心听完每一段对话。</p><ul class="login-benefits"><li><AppIcon name="check" :size="17" />浏览你在小宇宙订阅的播客</li><li><AppIcon name="check" :size="17" />探索分类，搜索播客与单集</li><li><AppIcon name="check" :size="17" />登录凭据仅在本机加密保存</li></ul><p class="login-alternative">想先听听看？<RouterLink to="/subscriptions" class="text-button">用 RSS 开始<AppIcon name="arrow" :size="14" /></RouterLink></p></div><div class="login-card"><h2>扫码登录</h2><p class="muted">使用手机小宇宙 App 扫一扫</p><div class="qr-frame"><img v-if="qr" :src="qr" alt="小宇宙登录二维码" /><div v-else class="qr-placeholder"><AppIcon :name="account.phase === 'creating' || account.phase === 'checking' ? 'refresh' : 'user'" :size="42" /><span>{{ account.phase === 'creating' ? '二维码生成中' : '准备好，就开始吧' }}</span></div></div><p class="login-hint" :class="{ 'text-danger': account.phase === 'error' }" role="status">{{ hint }}</p><button class="button primary wide" :disabled="account.isBusy || account.phase === 'checking'" @click="account.startLogin()">{{ account.isBusy ? '等待手机确认…' : account.phase === 'expired' ? '刷新二维码' : '获取登录二维码' }}</button><button v-if="account.isBusy" class="text-button cancel-login" @click="account.cancel()">取消登录</button><small>无需输入密码 · 请勿分享登录二维码</small></div></section><template v-else><section class="account-card"><CoverArt :src="account.user?.avatar" :title="account.nickname || '宇'" /><div class="grow"><span class="eyebrow">WELCOME BACK</span><h2>{{ account.nickname || '小宇宙听友' }}</h2><p class="muted"><span class="status-dot"></span>已连接 · 登录状态保存在本机</p></div><button class="button subtle" @click="account.logout()"><AppIcon name="logout" :size="17" />退出登录</button></section><p v-if="account.errorMessage" class="notice error" role="alert">{{ account.errorMessage }}</p><div class="stats-grid"><div class="stat-card"><span>已载入的官方订阅</span><strong>{{ official.count }}</strong><small>在「我的订阅」中查看与刷新</small></div><div class="stat-card"><span>本机收听足迹</span><strong>{{ history.entries.length }}</strong><small>记录进度，下次接着听</small></div><RouterLink to="/settings" class="stat-card"><span>按自己的节奏</span><strong class="stat-icon"><AppIcon name="settings" :size="32" /></strong><small>外观、倍速与播放偏好<AppIcon name="arrow" :size="14" /></small></RouterLink></div><RouterLink to="/subscriptions" class="feature-card account-library"><span class="feature-icon peach"><AppIcon name="library" :size="24" /></span><div><h3>回到你的声音收藏</h3><p>在「我的订阅」查看官方播客与本机 RSS 订阅。</p></div><AppIcon name="arrow" /></RouterLink></template><p class="legal-note">这是非官方桌面客户端，与小宇宙官方无隶属关系。账号功能依赖官方接口，接口调整可能影响使用；付费内容须在官方 App 内购买。</p></section></template>
